import{_ as r,c as s,o as a,ae as t}from"./chunks/framework.1y2w2LY9.js";const h=JSON.parse('{"title":"Security Policy","description":"","frontmatter":{},"headers":[],"relativePath":"SECURITY.md","filePath":"SECURITY.md"}'),i={name:"SECURITY.md"};function o(n,e,l,c,p,u){return a(),s("div",null,[...e[0]||(e[0]=[t('<h1 id="security-policy" tabindex="-1">Security Policy <a class="header-anchor" href="#security-policy" aria-label="Permalink to &quot;Security Policy&quot;">​</a></h1><p>This document describes how to responsibly report vulnerabilities and how security fixes are released for the package.</p><h2 id="supported-versions" tabindex="-1">Supported Versions <a class="header-anchor" href="#supported-versions" aria-label="Permalink to &quot;Supported Versions&quot;">​</a></h2><p>The project follows <strong><a href="https://semver.org/" target="_blank" rel="noreferrer">Semantic Versioning (SemVer)</a></strong>. <br> Security fixes are released as <strong>patch</strong> versions on the latest <strong>minor</strong> line. <br><strong>Older versions</strong> may receive fixes only for critical issues.</p><h2 id="reporting-a-vulnerability" tabindex="-1">Reporting a Vulnerability <a class="header-anchor" href="#reporting-a-vulnerability" aria-label="Permalink to &quot;Reporting a Vulnerability&quot;">​</a></h2><p>Do <strong>not</strong> open public issues for security problems. Use one of the private channels:</p><ul><li><strong>GitHub Security Advisory</strong>: <a href="https://github.com/MorevM/stylelint-plugin/security/advisories/new" target="_blank" rel="noreferrer">create a private report</a></li><li><strong>Email</strong>: <a href="mailto:max.seainside@gmail.com" target="_blank" rel="noreferrer">max.seainside@gmail.com</a></li></ul><p>A report should include description, impact, reproduction steps, and affected versions. <br> If the issue lies in a <strong>dependency</strong>, please mention the affected package and version.</p><h2 id="disclosure-process" tabindex="-1">Disclosure Process <a class="header-anchor" href="#disclosure-process" aria-label="Permalink to &quot;Disclosure Process&quot;">​</a></h2><ul><li>Receipt confirmed within <strong>2 business days</strong>.</li><li>Severity assessed and fix prepared.</li><li>Patch release published.</li><li>Advisory issued with credit to the reporter (if agreed).</li></ul><p>GitHub Security Advisories allow private coordination, linking to fixed releases, and optional CVE assignment.</p><h2 id="scope" tabindex="-1">Scope <a class="header-anchor" href="#scope" aria-label="Permalink to &quot;Scope&quot;">​</a></h2><p><strong>Relevant classes:</strong> ReDoS, code execution via unsafe input, path traversal, prototype pollution, supply-chain issues. <br><strong>Out of scope:</strong> stylistic rule behavior or non-security bugs.</p><h2 id="preferred-languages" tabindex="-1">Preferred Languages <a class="header-anchor" href="#preferred-languages" aria-label="Permalink to &quot;Preferred Languages&quot;">​</a></h2><p>Vulnerability reports are accepted in <strong>English</strong> or <strong>Russian</strong>.</p>',15)])])}const g=r(i,[["render",o]]);export{h as __pageData,g as default};
